   B:()=>S.filter(s=>s.score==='B'),C:()=>S.filter(s=>s.score==='C'),D:()=>S.filter(s=>s.score==='D'),
   buy:()=>S.filter(s=>s.rec==='buy'),rend:()=>S.filter(s=>s.yield>=5),
